import { createAction, createSlice } from '@reduxjs/toolkit';

// 1. Create a standalone global action
export const resetApp = createAction('app/reset');

// 2. A slice can listen to it using extraReducers
const userSlice = createSlice({
  name: 'user',
  initialState: { name: 'John' },
  reducers: {},
  extraReducers: (builder) => {
    // When the global reset action is dispatched anywhere in the app, do this:
    builder.addCase(resetApp, (state) => {
      state.name = null;
    });
  }
});
